25	 *
26	 * <p>The {@link #identityKey(String, String, String) identityKey} is the SHA-256, rendered as
27	 * lower-case hex, of the owner's normalized telephone, lower-cased email and the {@link
28	 * #soundex(String) Soundex} of its last name, joined with {@code '|'} separators. It is the single
29	 * key both the duplicate-detection check and the exposed {@code identityKey} field are computed
30	 * from, so the two never diverge.
31	 */
32	public final class IdentityKeys {
33	
34	    private IdentityKeys() {
35	    }
36	
37	    /**
38	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
39	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A {@code null}
40	     * telephone or email contributes an empty segment; the last name is always contributed via its
41	     * {@link #soundex(String) Soundex} encoding (empty when the last name is absent).
42	     *
43	     * @param telephone the owner's normalized (E.164) telephone, may be {@code null}
44	     * @param email     the owner's lower-cased email, may be {@code null}
45	     * @param lastName  the owner's last name, may be {@code null}
46	     * @return the 64-character lower-case hex identity key
47	     */
48	    public static String identityKey(String telephone, String email, String lastName) {
49	        String input = (telephone == null ? "" : telephone)
50	            + "|" + (email == null ? "" : email)
51	            + "|" + soundex(lastName);
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                .digest(input.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder hex = new StringBuilder(digest.length * 2);
56	            for (byte b : digest) {
57	                hex.append(String.format("%02x", b));
58	            }
59	            return hex.toString();
60	        } catch (NoSuchAlgorithmException ex) {
61	            throw new IllegalStateException("SHA-256 not available", ex);
62	        }
63	    }
64	
65	    /**
66	     * Computes the American Soundex code of a name: the retained first letter followed by up to
67	     * three digits encoding the following consonants (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2; d,t-&gt;3;
68	     * l-&gt;4; m,n-&gt;5; r-&gt;6), zero-padded to four characters. Adjacent letters with the same
69	     * code collapse to one; vowels (and y) separate same-coded consonants, while h and w are
70	     * transparent and do not. A {@code null} or letter-free name yields an empty string.
71	     *
72	     * @param name the name to encode, may be {@code null}
73	     * @return the four-character Soundex code, or an empty string when there is no letter to encode
74	     */
75	    public static String soundex(String name) {
76	        if (name == null) {
77	            return "";
78	        }
79	        StringBuilder letters = new StringBuilder();
80	        for (int i = 0; i < name.length(); i++) {
81	            char c = name.charAt(i);
82	            if (Character.isLetter(c)) {
83	                letters.append(Character.toUpperCase(c));
84	            }
85	        }
86	        if (letters.length() == 0) {
87	            return "";
88	        }
89	        StringBuilder code = new StringBuilder();
90	        code.append(letters.charAt(0));
91	        char previousCode = mappingCode(letters.charAt(0));
92	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
93	            char letter = letters.charAt(i);
94	            if (letter == 'H' || letter == 'W') {
95	                // Transparent: does not separate same-coded consonants, does not reset the run.
96	                continue;
97	            }
98	            char mapped = mappingCode(letter);
99	            if (mapped == '0') {
100	                // A vowel (or y) separates otherwise-identical codes.
101	                previousCode = '0';
102	                continue;
103	            }
104	            if (mapped != previousCode) {
105	                code.append(mapped);
106	            }
107	            previousCode = mapped;
108	        }
109	        while (code.length() < 4) {
110	            code.append('0');
111	        }
112	        return code.toString();
113	    }
114	
115	    /**
116	     * Maps a single upper-case letter to its Soundex digit ('0' for vowels, y, h and w).
117	     */
118	    private static char mappingCode(char letter) {
119	        return switch (letter) {
120	            case 'B', 'F', 'P', 'V' -> '1';
121	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
122	            case 'D', 'T' -> '3';
123	            case 'L' -> '4';
124	            case 'M', 'N' -> '5';
125	            case 'R' -> '6';
126	            default -> '0';
127	        };
128	    }
129	}
