281	     * the postcode is absent, not 4 digits, or in no known range.
282	     */
283	    private String regionFromPostcode(String postcode) {
284	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
285	            return null;
286	        }
287	        int value = Integer.parseInt(postcode);
288	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
289	            int[] range = entry.getValue();
290	            if (value >= range[0] && value <= range[1]) {
291	                return entry.getKey();
292	            }
293	        }
294	        return null;
295	    }
