297	    /**
298	     * The minimum {@link #membershipLevel(Owner) membership level} at which an owner is a
299	     * {@code PREMIUM} tier for {@link #ownerSegment(Owner) segmentation}; below it the owner is
300	     * {@code STANDARD}.
301	     */
302	    private static final int PREMIUM_TIER_MIN_LEVEL = 3;
303	
304	    /**
305	     * The regions treated as {@code METRO} for {@link #ownerSegment(Owner) segmentation}; any other
306	     * locality (e.g. {@code UNKNOWN}) is {@code REGIONAL}.
307	     */
308	    private static final java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
309	
310	    /**
311	     * Derives the owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} (one of
312	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
313	     * {@code STANDARD_REGIONAL}). TIER is {@code PREMIUM} when the owner's
314	     * {@link #membershipLevel(Owner) membership level} is {@value #PREMIUM_TIER_MIN_LEVEL} or more,
315	     * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
316	     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
317	     * {@code REGIONAL}.
318	     */
319	    protected OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
320	        String tier = membershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
321	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
322	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
323	    }
324	
325	    /**
326	     * The minimum household size (counting the owner itself) that earns household membership
327	     * points.
328	     */
329	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
330	
331	    /**
332	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
333	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
334	     * clears this threshold.
335	     */
336	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
337	
338	    /**
339	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
340	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
341	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
342	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
343	     */
344	    protected Integer membershipPoints(Owner owner) {
345	        int points = 0;
346	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
347	        if (hasEmail) {
348	            points += 2;
349	        }
350	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
351	        if (noNamesakes) {
352	            points += 1;
353	        }
354	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
355	            points += 2;
356	        }
357	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
358	            points += 3;
359	        }
360	        return points;
361	    }
362	
363	    /**
364	     * Derives the owner's membership level, capped by their household. The level starts from the
365	     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
366	     * above the current maximum level among the owner's existing household members (other owners
367	     * sharing its {@code householdId}). When the owner has no existing household member no cap
368	     * applies and the points-based level is returned unchanged.
369	     */
370	    protected Integer membershipLevel(Owner owner) {
371	        int level = uncappedMembershipLevel(owner);
372	        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
373	            .mapToInt(this::uncappedMembershipLevel)
374	            .max();
375	        if (maxHouseholdLevel.isEmpty()) {
376	            return level;
377	        }
378	        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
379	    }
380	
381	    /**
382	     * The owner's points-based membership level, before the household ceiling is applied: level 1
383	     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
384	     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
385	     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
386	     * household members do not recurse into each other's caps.
387	     */
388	    private int uncappedMembershipLevel(Owner owner) {
389	        int points = membershipPoints(owner);
390	        if (points <= 1) {
391	            return 1;
392	        }
393	        if (points <= 3) {
394	            return 2;
395	        }
396	        if (points <= 5) {
397	            return 3;
398	        }
399	        return 4;
400	    }
401	
402	    /**
403	     * The owner's existing household members: every other owner (excluding the owner itself) sharing
404	     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
405	     * of its household.
406	     */
407	    private Stream<Owner> otherHouseholdMembers(Owner owner) {
408	        String householdId = owner.getHouseholdId();
409	        if (householdId == null) {
410	            return Stream.empty();
411	        }
412	        return this.clinicService.findAllOwners().stream()
413	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
414	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
415	    }
416	
417	    /**
418	     * The number of owners in this owner's household — the count of owners (including this one)
419	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
420	     */
421	    private long householdSize(Owner owner) {
422	        String householdId = owner.getHouseholdId();
423	        if (householdId == null) {
424	            return 0;
425	        }
426	        return this.clinicService.findAllOwners().stream()
427	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
428	            .count();
429	    }
430	
431	    /**
432	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
433	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
434	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
435	     * owner without a registration date is treated as having no tenure.
436	     */
437	    private long tenureFiscalYears(Owner owner) {
438	        LocalDate registrationDate = owner.getRegistrationDate();
439	        if (registrationDate == null) {
440	            return 0;
441	        }
442	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
443	    }
444	
445	    /**
446	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
447	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
448	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
449	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
450	     * owner has no registration date.
451	     */
452	    protected Boolean bulkSignupWarning(Owner owner) {
453	        LocalDate registrationDate = owner.getRegistrationDate();
454	        if (registrationDate == null) {
455	            return false;
456	        }
457	        long othersOnDay = this.clinicService.findAllOwners().stream()
458	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
459	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
460	            .count();
461	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
462	    }
463	
464	    /**
465	     * Flags a city approaching its hard capacity limit: {@code true} when this owner's city already
466	     * holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one owners,
467	     * inclusive (excluding the owner itself), so on a create the flag reflects the owners that
468	     * pre-existed it in that city, matching the count the per-city capacity limit is enforced
469	     * against. Cities are compared case-insensitively, as they are for the capacity limit. Returns
470	     * {@code false} when the owner has no city.
471	     */
472	    protected Boolean capacityWarning(Owner owner) {
473	        String city = owner.getCity();
474	        if (city == null) {
475	            return false;
476	        }
477	        long othersInCity = this.clinicService.findAllOwners().stream()
478	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
479	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
480	            .count();
481	        return othersInCity >= CAPACITY_WARNING_THRESHOLD && othersInCity < CITY_CAPACITY;
482	    }
483	
484	    /**
485	     * The known disposable/throwaway email providers, mirroring the create endpoint's blocklist.
486	     * An email whose domain exactly matches one of these is rejected on create; the risk flag
487	     * instead catches domains that are merely <em>adjacent</em> to one of them (see
488	     * {@link #disposableAdjacentEmail(Owner)}).
489	     */
490	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
491	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
492	
493	    /**
494	     * The second-level labels of the known disposable providers (e.g. {@code mailinator} from
495	     * {@code mailinator.com}), used to recognise disposable-adjacent domains regardless of their
496	     * top-level domain or any subdomain in front.
497	     */
498	    private static final java.util.Set<String> DISPOSABLE_DOMAIN_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
499	        .map(domain -> domain.substring(0, domain.lastIndexOf('.')))
500	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
501	
502	    /**
503	     * Derives the owner's {@code riskFlag}: {@code true} when any of these hold, otherwise
504	     * {@code false}. The owner is a possible duplicate ({@code possibleDuplicate} is true), the
505	     * email domain is {@link #disposableAdjacentEmail(Owner) disposable-adjacent}, or the city is
506	     * over its soft capacity (the {@link #capacityWarning(Owner) capacity warning} is raised).
507	     */
508	    protected Boolean riskFlag(Owner owner) {
509	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
510	            || disposableAdjacentEmail(owner)
511	            || Boolean.TRUE.equals(capacityWarning(owner));
512	    }
513	
514	    /**
515	     * Whether the owner's email domain is <em>disposable-adjacent</em>: it shares a second-level
516	     * label with a known disposable provider (mailinator, tempmail, guerrillamail), so a subdomain
517	     * ({@code promo.mailinator.com}) or an alternate top-level domain ({@code tempmail.co}) that
518	     * slips past the create endpoint's exact-match blocklist is still recognised. Returns
519	     * {@code false} when the owner has no email or the domain shares no such label.
520	     */
521	    protected boolean disposableAdjacentEmail(Owner owner) {
522	        String email = owner.getEmail();
523	        if (email == null) {
524	            return false;
525	        }
526	        int at = email.lastIndexOf('@');
527	        if (at < 0 || at == email.length() - 1) {
528	            return false;
529	        }
530	        String domain = email.substring(at + 1).toLowerCase(java.util.Locale.ROOT);
531	        for (String label : domain.split("\\.")) {
532	            if (DISPOSABLE_DOMAIN_LABELS.contains(label)) {
533	                return true;
534	            }
535	        }
536	        return false;
537	    }
538	
539	    /**
540	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
541	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
542	     * title was supplied (a {@code null} or blank title).
543	     */
544	    protected String salutation(Owner owner) {
545	        String title = owner.getTitle();
546	        String lastName = owner.getLastName();
547	        if (title == null || title.isBlank()) {
548	            return lastName;
549	        }
550	        return title + " " + lastName;
551	    }
552	
553	    /**
554	     * Derives the owner's {@code selfLink}: the canonical link to this owner resource, formatted
555	     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
556	     */
557	    protected String selfLink(Owner owner) {
558	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
559	    }
560	
561	    public abstract Owner toOwner(OwnerDto ownerDto);
562	
563	    @Mapping(target = "id", ignore = true)
564	    @Mapping(target = "pets", ignore = true)
565	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
566	
567	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
568	
569	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
570	
571	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
572	        OwnerPageDto ownerPageDto = new OwnerPageDto();
573	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
574	        ownerPageDto.setPage(ownerPage.getNumber());
575	        ownerPageDto.setSize(ownerPage.getSize());
576	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
577	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
578	        return ownerPageDto;
579	    }
580	}
