public enum OwnerSegmentEnum {
  PREMIUM_METRO("PREMIUM_METRO"),

  PREMIUM_REGIONAL("PREMIUM_REGIONAL"),

  STANDARD_METRO("STANDARD_METRO"),

  STANDARD_REGIONAL("STANDARD_REGIONAL");

  private final String value;

  OwnerSegmentEnum(String value) {
    this.value = value;
  }

  @JsonValue
  public String getValue() {
    return value;
  }

  @Override
  public String toString() {
    return String.valueOf(value);
  }

  @JsonCreator
  public static OwnerSegmentEnum fromValue(String value) {
    for (OwnerSegmentEnum b : OwnerSegmentEnum.values()) {
      if (b.value.equals(value)) {
        return b;
      }
    }
    throw new IllegalArgumentException("Unexpected value '" + value + "'");
  }
}

